// Calculate previous month range
const now = new Date();
const monthEnd = new Date(now.getFullYear(), now.getMonth(), 0);
const monthStart = new Date(monthEnd.getFullYear(), monthEnd.getMonth(), 1);

const fmt = (d) => d.toISOString().split('T')[0];

return [{
  json: {
    monthStart: fmt(monthStart),
    monthEnd: fmt(monthEnd),
    year: monthEnd.getFullYear(),
    month: monthEnd.getMonth() + 1,
    jiraBaseUrl: 'https://casaametller.atlassian.net',
    kpiApiUrl: 'http://backend:8000'
  }
}];

const issues = $('JQL All Resolved Issues').first().json.issues || [];

return issues.map(issue => ({
  json: {
    issueKey: issue.key,
    team: issue.fields?.customfield_11006 || 'Unknown',
    issueType: issue.fields?.issuetype?.name || '',
    priority: issue.fields?.priority?.name || ''
  }
}));

// ── SRV-FRT + SRV-RES + SRV-TTS from SLA data ──
const slaResults = $input.all();
const preparedItems = $('Prepare SLA Lookup').all();
const dates = $('Calculate Month Range').first().json;

const frtByTeam = {};
let resTotal = 0, resMet = 0;
let ttsTotal = 0, ttsMet = 0;

for (let i = 0; i < slaResults.length; i++) {
  const sla = slaResults[i].json;
  const meta = preparedItems[i]?.json || {};
  const team = meta.team || 'Unknown';
  const values = sla.values || sla.slaValues || [];

  for (const metric of values) {
    const name = (metric.name || metric.metric?.name || '').toLowerCase();
    const cycle = metric.completedCycles?.[0];
    if (!cycle) continue;
    const breached = cycle.breached === true || cycle.hasFailed === true;

    if (name.includes('first response') || name.includes('primera resposta')) {
      if (!frtByTeam[team]) frtByTeam[team] = { met: 0, total: 0 };
      frtByTeam[team].total++;
      if (!breached) frtByTeam[team].met++;
    }
    if (name.includes('resolution') || name.includes('resolució')) {
      resTotal++;
      if (!breached) resMet++;
    }
    if (name.includes('scale') || name.includes('escalat')) {
      ttsTotal++;
      if (!breached) ttsMet++;
    }
  }
}

let frtTotalMet = 0, frtTotalCount = 0;
const teamDetails = [];
for (const [team, data] of Object.entries(frtByTeam)) {
  const pct = data.total > 0 ? Math.round((data.met / data.total) * 10000) / 100 : 100;
  teamDetails.push(`${team}: ${pct}%`);
  frtTotalMet += data.met;
  frtTotalCount += data.total;
}
const frtPct = frtTotalCount > 0 ? Math.round((frtTotalMet / frtTotalCount) * 10000) / 100 : 100;
const resPct = resTotal > 0 ? Math.round((resMet / resTotal) * 10000) / 100 : 100;
const ttsPct = ttsTotal > 0 ? Math.round((ttsMet / ttsTotal) * 10000) / 100 : 100;

// Output 3 items — one per KPI
return [
  { json: { kpi_code: 'SRV-FRT', year: dates.year, month: dates.month, value: frtPct, notes: `First Response SLA: ${frtTotalMet}/${frtTotalCount}. ${teamDetails.join(', ')}`, workflow_id: 'jira-sdit-monthly-sla' } },
  { json: { kpi_code: 'SRV-RES', year: dates.year, month: dates.month, value: resPct, notes: `Resolution SLA: ${resMet}/${resTotal} (${resPct}%)`, workflow_id: 'jira-sdit-monthly-sla' } },
  { json: { kpi_code: 'SRV-TTS', year: dates.year, month: dates.month, value: ttsPct, notes: `Time to Scale SLA: ${ttsMet}/${ttsTotal} (${ttsPct}%)`, workflow_id: 'jira-sdit-monthly-sla' } }
];

// ── SRV-REC: Incidents recurrents per botiga ──
const issues = $('JQL Incidents Sistemes').first().json.issues || [];
const dates = $('Calculate Month Range').first().json;

const byStore = {};
for (const issue of issues) {
  const cuField = issue.fields?.customfield_10959;
  const store = typeof cuField === 'string' ? cuField : (cuField?.value || cuField?.name || 'Unknown');
  byStore[store] = (byStore[store] || 0) + 1;
}

const storesOverLimit = Object.entries(byStore).filter(([, count]) => count > 3).sort((a, b) => b[1] - a[1]);
const topOffenders = storesOverLimit.slice(0, 5).map(([store, count]) => `${store}: ${count}`).join(', ');

// Output 1 item
return [
  { json: { kpi_code: 'SRV-REC', year: dates.year, month: dates.month, value: storesOverLimit.length, notes: `${storesOverLimit.length} botigues amb >3 incidents. ${topOffenders ? 'Top: ' + topOffenders : 'Cap botiga supera el llindar.'}`, workflow_id: 'jira-sdit-monthly-sla' } }
];

// ── SRV-FCR: First Contact Resolution ──
// Input 0 = JQL FCR Total Resolved, Input 1 = JQL FCR Escalated
const items = $input.all();
const totalResolved = (items[0]?.json?.issues || []).length;
const escalated = (items[1]?.json?.issues || []).length;
const dates = $('Calculate Month Range').first().json;

const withoutEscalation = totalResolved - escalated;
const pct = totalResolved > 0 ? Math.round((withoutEscalation / totalResolved) * 10000) / 100 : 100;

return [
  { json: { kpi_code: 'SRV-FCR', year: dates.year, month: dates.month, value: pct, notes: `${withoutEscalation}/${totalResolved} resolts sense escalar (${pct}%). Escalats: ${escalated}`, workflow_id: 'jira-sdit-monthly-sla' } }
];

// ── SRV-12: Peticions Ateses/mes ──
// ── SRV-11: Cost per Tiquet (worklogs × 25€/h / resolts) ──
const issues = $('JQL Resolved + Worklogs').first().json.issues || [];
const dates = $('Calculate Month Range').first().json;
const HOURLY_RATE = 25;
const monthStartMs = new Date(dates.monthStart).getTime();
const monthEndMs = new Date(dates.monthEnd + 'T23:59:59Z').getTime();

const resolvedCount = issues.length;

// Sum worklogs within the month
let totalSeconds = 0;
for (const issue of issues) {
  const worklogs = issue.fields?.worklog?.worklogs || [];
  for (const wl of worklogs) {
    const started = new Date(wl.started).getTime();
    if (started >= monthStartMs && started <= monthEndMs) {
      totalSeconds += (wl.timeSpentSeconds || 0);
    }
  }
}
const totalHours = totalSeconds / 3600;
const totalCost = totalHours * HOURLY_RATE;
const costPerTicket = resolvedCount > 0 ? Math.round((totalCost / resolvedCount) * 100) / 100 : 0;

return [
  { json: { kpi_code: 'SRV-12', year: dates.year, month: dates.month, value: resolvedCount, notes: `${resolvedCount} tickets resolts`, workflow_id: 'jira-sdit-monthly-sla' } },
  { json: { kpi_code: 'SRV-11', year: dates.year, month: dates.month, value: costPerTicket, notes: `${Math.round(totalHours)}h × ${HOURLY_RATE}€/h = ${Math.round(totalCost)}€ / ${resolvedCount} tickets`, workflow_id: 'jira-sdit-monthly-sla' } }
];

// ── SRV-CHR: Peticions de Canvi al mes ──
const issues = $('JQL Changes Created').first().json.issues || [];
const dates = $('Calculate Month Range').first().json;
return [
  { json: { kpi_code: 'SRV-CHR', year: dates.year, month: dates.month, value: issues.length, notes: `${issues.length} changes creats`, workflow_id: 'jira-sdit-monthly-sla' } }
];

// All items from 6 branches are now merged (appended)
// Each item has a .json with kpi_code, year, month, value, notes, workflow_id
const allItems = $input.all().map(item => item.json);

return [{
  json: {
    items: allItems,
    workflow_id: 'jira-sdit-monthly-sla'
  }
}];
